import{_ as t,o as a,c as o,a7 as r}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Vault Nest Support","description":"Standalone support information for Vault Nest.","frontmatter":{"title":"Vault Nest Support","description":"Standalone support information for Vault Nest.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/vault-nest.md","filePath":"support/vault-nest.md"}'),s={name:"support/vault-nest.md"};function n(i,e,l,p,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="vault-nest-support" tabindex="-1">Vault Nest Support <a class="header-anchor" href="#vault-nest-support" aria-label="Permalink to &quot;Vault Nest Support&quot;">​</a></h1><p>For Vault Nest support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the Vault Nest version, Android version, device model, a description of the issue, and safe reproduction steps when possible.</p><p>Never email your master password, saved credentials, OTP secrets, backup codes, intrusion-evidence images, <code>.vaultpack</code> files, or CSV exports. The developer cannot recover or decrypt a vault.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Lost master password:</strong> Vault Nest has no recovery service. Restore a usable backup only if you know that backup&#39;s passphrase and original master password.</li><li><strong>Biometric unlock unavailable:</strong> unlock with the full master password, then review biometric settings. Enrollment changes can invalidate the device key.</li><li><strong>Backup restore fails:</strong> confirm that the selected file is a Vault Nest <code>.vaultpack</code> file and that the separate backup passphrase is correct.</li><li><strong>Notifications unavailable:</strong> grant notification permission in Android and retry the reminder or credential-copy action.</li><li><strong>Camera evidence unavailable:</strong> the feature requires Android, a front camera, explicit camera permission, and the setting to be enabled.</li><li><strong>CSV export:</strong> treat the file as readable sensitive information and delete it after importing it into the intended destination.</li></ul>',6)])])}const m=t(s,[["render",n]]);export{f as __pageData,m as default};
